.mapping-editor-canvas { position: relative; width: 100%; height: 100%; overflow: hidden; isolation: isolate; }
.mapping-editor-canvas .tl-background { background: var(--canvas-background, var(--surface-canvas)); }
.mapping-editor-overlay { position: absolute; left: 0; top: 0; transform-origin: 0 0; pointer-events: none; }
.mapping-editor-overlay .mapping-poc-graph-stage { pointer-events: none; }
.mapping-editor-overlay button, .mapping-editor-overlay input, .mapping-editor-overlay textarea,
.mapping-editor-overlay select, .mapping-editor-overlay [data-mapping-static-ui] { pointer-events: auto; }
.mapping-native-shape { overflow: visible; pointer-events: auto; color: var(--text-primary); }
.mapping-native-body { isolation: isolate; position: relative; width: 100%; height: 100%; }
.mapping-native-body > .mapping-grid-box { inset: 0; width: 100%; height: 100%; }
.mapping-native-body .mapping-poc-ascii { margin: 0; padding: 0; }
/* Retained regions are highlights; their native DOM must leave labels clickable. */
.mapping-native-container, .mapping-native-selection { pointer-events: none; }
.mapping-native-body > .selection-effect-frame { position: relative; left: 0 !important; top: 0 !important; }
.mapping-native-body > .local-chat-convo { left: 0 !important; top: 0 !important; }
.mapping-editor-canvas .mapping-poc-cell-probe { pointer-events: none; }


.mapping-editor-overlay .mapping-poc-graph-stage { margin: 0; }
.mapping-editor-overlay pre.mapping-poc-ascii { margin: 0; }
/* Leave the SDK's own production-license notice unobstructed. */
.mapping-editor-canvas > .diagram-canvas__controls { right: 12px; top: 12px; bottom: auto;
  max-width: calc(100% - 24px); flex-wrap: wrap; }
.mapping-editor-canvas > .diagram-canvas__controls button[aria-pressed="true"] { background: color-mix(in srgb, var(--accent-primary) 16.863%, transparent); color: var(--fg); }
@media (any-pointer: coarse) {
  .mapping-editor-canvas > .diagram-canvas__controls { font-size: var(--text-md); }
  .mapping-editor-canvas > .diagram-canvas__controls button { min-width: 44px; min-height: 44px; padding: var(--space-4) var(--space-6); }
}

/* Apply touch policy at the canvas itself; sibling source panels retain scrolling. */
.mapping-editor-canvas .tl-canvas { touch-action: none; }
/* The inverse-scaled handle sits above/left of the frame, clear of labels and frame buttons. */
.mapping-diagram-move-handle { position: absolute; left: 0; top: 0; transform-origin: left top;
  width: 44px; height: 44px; min-width: 44px; min-height: 44px; pointer-events: auto;
  z-index: 5; cursor: move; touch-action: none; font-size: 24px; }

.canvas-treemap-tint { position: absolute; z-index: -1; pointer-events: none; background: color-mix(in srgb, var(--treemap-diagram-color) var(--canvas-identity-opacity), transparent); }

.diagram-side-panel { background: var(--surface-canvas); color: var(--fg); box-shadow: inset 0 0 0 1px var(--border-strong); }
.diagram-side-panel-toolbar { background: var(--surface-raised); color: var(--fg); }
.diagram-side-panel-toolbar button, .diagram-side-panel-toolbar select, .diagram-alternative-controls button {
  background: var(--control-background); color: var(--fg); border: 1px solid var(--border); border-radius: var(--radius-sm); font: inherit; cursor: pointer;
}
.diagram-side-panel-toolbar button:hover, .diagram-alternative-controls button:hover { background: var(--surface-hover); }
.diagram-side-panel-toolbar button[aria-pressed=true], .diagram-alternative-controls button[aria-pressed=true] { background: var(--surface-selected); }
.diagram-side-panel [role=alert] { background: var(--surface-raised); color: var(--diff-deleted-text); }
